@@ -15,3 +15,58 @@ export const isGemini25Plus = (baseModel: string) => {
 };
 export const isFlux1 = (baseModel: string) => baseModel.startsWith('flux1');
 export const isFlux2 = (baseModel: string) => baseModel.startsWith('flux2');
+
+/**
+ * Model capabilities for reference image support.
+ * This is the single source of truth for model-specific behavior.
+ */
+export interface ModelCapabilities {
+  /** Maximum number of reference images supported (0 = no img2img support) */
+  maxReferenceImages: number;
+  /** Whether the model supports reference images at all */
+  supportsReferenceImages: boolean;
+  /** Whether aspect ratio can be changed when using reference images */
+  supportsAspectRatioWithReferenceImages: boolean;
+}
+
+/**
+ * Get the capabilities for a given base model.
+ * Centralizes all model-specific capability logic in one place.
+ */
+export const getModelCapabilities = (baseModel: string): ModelCapabilities => {
+  // FLUX2: No img2img support
+  if (isFlux2(baseModel)) {
+    return {
+      maxReferenceImages: 0,
+      supportsReferenceImages: false,
+      supportsAspectRatioWithReferenceImages: false
+    };
+  }
+
+  // Gemini models: 16 reference images
+  if (isGeminiModel(baseModel)) {
+    return {
+      maxReferenceImages: 16,
+      supportsReferenceImages: true,
+      // Only Nanobanana Pro supports aspect ratio with reference images
+      supportsAspectRatioWithReferenceImages:
+        baseModel === BASE_MODEL_NANO_BANANA_PRO
+    };
+  }
+
+  // GPT models: 16 reference images
+  if (isGptModel(baseModel)) {
+    return {
+      maxReferenceImages: 16,
+      supportsReferenceImages: true,
+      supportsAspectRatioWithReferenceImages: false
+    };
+  }
+
+  // Default (FLUX1, others): 1 reference image
+  return {
+    maxReferenceImages: 1,
+    supportsReferenceImages: true,
+    supportsAspectRatioWithReferenceImages: false
+  };
+};
