+  const mergedProps = { ...defaultProps, ...props } as Parameters<
+    typeof FloatingTextarea
+  >[0];
+  return render(
+    <QueryClientProvider client={queryClient}>
+      <NextIntlClientProvider locale="en" messages={mockMessages}>
+        <FloatingTextarea {...mergedProps} />
