+
+      // First image within limit should have muted styling
+      const mutedBadges = container.querySelectorAll(
+        'span.bg-muted.text-muted-foreground.rounded-full'
+      );
+      expect(mutedBadges).toHaveLength(1);
+      expect(mutedBadges[0].textContent).toBe('1');
+
+      // Images 2 and 3 exceed limit, should have destructive (red) styling
+      const destructiveBadges = container.querySelectorAll(
+        'span.bg-destructive.text-destructive-foreground.rounded-full'
+      );
+      expect(destructiveBadges).toHaveLength(2);
+
+      // Verify all badges show correct sequential numbers (1, 2, 3)
+      const allBadgeTexts = [
+        ...Array.from(mutedBadges).map((b) => b.textContent),
+        ...Array.from(destructiveBadges).map((b) => b.textContent)
