+        referenceImages: createReferenceImages(3),
+        maxReferenceImages: 1,
+        hasExcessReferenceImages: true,
+        excessCount: 2
+      });
+
+      // First image should have badge "1" with muted styling
+      const mutedBadges = container.querySelectorAll(
+        'span.bg-muted.text-muted-foreground.rounded-full'
+      );
+      expect(mutedBadges).toHaveLength(1);
+      expect(mutedBadges[0].textContent).toBe('1');
+    });
+
+    it('should disable generate button when there are excess images', () => {
+      renderWithProviders({
+        referenceImages: createReferenceImages(3),
+        maxReferenceImages: 1,
+        hasExcessReferenceImages: true,
+        excessCount: 2
+      });
+
+      const generateButton = screen.getByRole('button', { name: /generate/i });
+      expect(generateButton).toBeDisabled();
+    });
+
+    it('should show warning message when there are excess images', () => {
