+        referenceImages: createReferenceImages(3),
+        maxReferenceImages: 1,
+        hasExcessReferenceImages: true,
+        excessCount: 2
+      });
+
+      // Check for the warning message
+      expect(screen.getByText(/Remove 2 image\(s\)/)).toBeInTheDocument();
+    });
+
+    it('should apply red border styling to excess image thumbnails', () => {
