+        maxReferenceImages: 1,
+        hasExcessReferenceImages: true,
+        excessCount: 2
+      });
+
+      // Check for elements with destructive border class
+      const excessThumbnails = container.querySelectorAll('.border-destructive');
+      expect(excessThumbnails.length).toBe(2);
+    });
+  });
+
+  describe('edge cases', () => {
+    it('should handle exactly at the limit (no excess)', () => {
+      const { container } = renderWithProviders({
+        referenceImages: createReferenceImages(1),
+        maxReferenceImages: 1,
